xpath.script:
function selectAllLeads() {
    const checkboxes = document.querySelectorAll('.opportunityId');
    checkboxes.forEach(checkbox => {
        checkbox.checked = true;
    });
}

t.script:
document.addEventListener('DOMContentLoaded', function() {
const form = document.querySelector('.js_website_submit_form');

form.addEventListener('submit', function(event) {
event.preventDefault();

// Get the input values
const nameInput = form.querySelector('input[name="name"]');
const salesVolumeInput = form.querySelector('input[name="sales_volume"]');

// Reset any existing error messages
clearErrors();

// Validate name
if (!nameInput.value.trim()) {
showError(nameInput, 'Name is required');
nameInput.focus();
return;
}

// Validate sales volume
const salesVolume = parseFloat(salesVolumeInput.value);
if (!salesVolume || salesVolume <= 0) {
showError(salesVolumeInput, 'Sales volume must be greater than zero');
salesVolumeInput.focus();
return;
}

// If validation passes, submit the form
form.submit();
});

function showError(inputElement, message) {
// Create error message element
const errorDiv = document.createElement('div');
errorDiv.className = 'invalid-feedback d-block';
errorDiv.textContent = message;

// Add error class to input
inputElement.classList.add('is-invalid');

// Insert error message after input
inputElement.parentNode.appendChild(errorDiv);
}

function clearErrors() {
// Remove all error messages
const errorMessages = form.querySelectorAll('.invalid-feedback');
errorMessages.forEach(error => error.remove());

// Remove error classes from inputs
const invalidInputs = form.querySelectorAll('.is-invalid');
invalidInputs.forEach(input => input.classList.remove('is-invalid'));
}
});
